<?php
declare(strict_types=1);
require __DIR__ . '/auth-lib.php';

const QUEBEC_VOTE_RESET = '2026-09-06-photo-links';

const QUEBEC_DECISIONS = [
    'history' => ['individuell','klassisch','figur'],
    'nature' => ['montmorency','combo','island'],
    'citadelle' => ['citadelle','plains','both'],
    'foodtour' => ['food','histfood','dinner'],
    'night' => ['walk','ferry','ghost'],
    'restaurant' => ['traditional','regional','bistro','steak','fine','casual'],
];

function quebec_empty_data(): array { return ['ratings' => [], 'choices' => [], 'comments' => [], 'voteReset' => '']; }
function quebec_apply_vote_reset(array $data): array {
    $data = array_merge(quebec_empty_data(), $data);
    if (($data['voteReset'] ?? '') !== QUEBEC_VOTE_RESET) {
        $data['ratings'] = [];
        $data['choices'] = [];
        $data['voteReset'] = QUEBEC_VOTE_RESET;
    }
    return $data;
}
function quebec_clean($value, int $limit): string {
    $text = trim(strip_tags((string) $value));
    return function_exists('mb_substr') ? mb_substr($text, 0, $limit) : substr($text, 0, $limit);
}
function quebec_read(string $file): array {
    if (!is_file($file)) return quebec_apply_vote_reset(quebec_empty_data());
    $raw = file_get_contents($file);
    $decoded = is_string($raw) ? json_decode($raw, true) : null;
    $data = is_array($decoded) ? array_merge(quebec_empty_data(), $decoded) : quebec_empty_data();
    $needsReset = (($data['voteReset'] ?? '') !== QUEBEC_VOTE_RESET);
    $data = quebec_apply_vote_reset($data);
    if ($needsReset) @file_put_contents($file, json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), LOCK_EX);
    return $data;
}
function quebec_json(int $status, array $payload): void {
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');
    echo json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}
function quebec_view(array $data, string $currentProfile): array {
    $averages = [];
    foreach (QUEBEC_DECISIONS as $id => $_) {
        $ratings = is_array($data['ratings'][$id] ?? null) ? $data['ratings'][$id] : [];
        $values = array_values(array_filter($ratings, fn($v) => is_int($v) && $v >= 1 && $v <= 5));
        $averages[$id] = ['average' => $values ? round(array_sum($values) / count($values), 1) : null, 'count' => count($values)];
    }
    return ['ratings' => $data['ratings'], 'choices' => $data['choices'], 'comments' => $data['comments'], 'averages' => $averages, 'currentProfile' => $currentProfile, 'profiles' => CANADA_PROFILES];
}

if (isset($_GET['api'])) {
    $currentProfile = canada_require_api();
    $dataDir = __DIR__ . '/data';
    $dataFile = $dataDir . '/quebec-decisions.json';
    $method = $_SERVER['REQUEST_METHOD'] ?? 'GET';
    if ($method === 'GET') quebec_json(200, quebec_view(quebec_read($dataFile), $currentProfile));
    if ($method !== 'POST') quebec_json(405, ['error' => 'Methode nicht erlaubt']);
    if (!canada_origin_ok()) quebec_json(403, ['error' => 'Ungültige Herkunft']);
    canada_require_csrf();
    $raw = file_get_contents('php://input');
    if (!is_string($raw) || strlen($raw) > 16000) quebec_json(400, ['error' => 'Ungültige Anfrage']);
    $body = json_decode($raw, true);
    if (!is_array($body)) quebec_json(400, ['error' => 'Ungültige Anfrage']);
    $decision = quebec_clean($body['decision'] ?? '', 40);
    if (!isset(QUEBEC_DECISIONS[$decision])) quebec_json(422, ['error' => 'Entscheidung nicht gefunden']);
    $action = (string) ($body['action'] ?? '');
    if (!is_dir($dataDir) && !mkdir($dataDir, 0755, true) && !is_dir($dataDir)) quebec_json(500, ['error' => 'Speicher nicht verfügbar']);
    $handle = fopen($dataFile, 'c+');
    if ($handle === false || !flock($handle, LOCK_EX)) quebec_json(500, ['error' => 'Speicher nicht verfügbar']);
    $storedRaw = stream_get_contents($handle);
    $data = is_string($storedRaw) && $storedRaw !== '' ? json_decode($storedRaw, true) : null;
    $data = quebec_apply_vote_reset(is_array($data) ? $data : quebec_empty_data());
    if ($action === 'rating') {
        $rating = (int) ($body['rating'] ?? 0);
        if ($rating < 1 || $rating > 5) { flock($handle, LOCK_UN); fclose($handle); quebec_json(422, ['error' => 'Bitte 1 bis 5 Sterne wählen']); }
        if (!isset($data['ratings'][$decision]) || !is_array($data['ratings'][$decision])) $data['ratings'][$decision] = [];
        $data['ratings'][$decision][$currentProfile] = $rating;
    } elseif ($action === 'choice') {
        $choice = quebec_clean($body['choice'] ?? '', 40);
        if (!in_array($choice, QUEBEC_DECISIONS[$decision], true)) { flock($handle, LOCK_UN); fclose($handle); quebec_json(422, ['error' => 'Bitte eine angebotene Variante wählen']); }
        if (!isset($data['choices'][$decision]) || !is_array($data['choices'][$decision])) $data['choices'][$decision] = [];
        $data['choices'][$decision][$currentProfile] = $choice;
    } elseif ($action === 'comment') {
        $text = quebec_clean($body['text'] ?? '', 1000);
        $parentId = quebec_clean($body['parentId'] ?? '', 80);
        if ($text === '') { flock($handle, LOCK_UN); fclose($handle); quebec_json(422, ['error' => 'Bitte einen Kommentar eingeben']); }
        if (!isset($data['comments'][$decision]) || !is_array($data['comments'][$decision])) $data['comments'][$decision] = [];
        if (count($data['comments'][$decision]) >= 300) { flock($handle, LOCK_UN); fclose($handle); quebec_json(422, ['error' => 'Zu viele Kommentare']); }
        if ($parentId !== '') {
            $parent = null;
            foreach ($data['comments'][$decision] as $candidate) if (($candidate['id'] ?? '') === $parentId) { $parent = $candidate; break; }
            if (!$parent || !empty($parent['parentId']) || !empty($parent['deleted'])) { flock($handle, LOCK_UN); fclose($handle); quebec_json(422, ['error' => 'Antwort nicht möglich']); }
        }
        $data['comments'][$decision][] = ['id' => bin2hex(random_bytes(12)), 'profile' => $currentProfile, 'text' => $text, 'parentId' => $parentId ?: null, 'createdAt' => gmdate('c')];
    } elseif ($action === 'delete-comment') {
        $commentId = quebec_clean($body['commentId'] ?? '', 80);
        $comments = is_array($data['comments'][$decision] ?? null) ? $data['comments'][$decision] : [];
        $target = null;
        foreach ($comments as $i => $comment) if (($comment['id'] ?? '') === $commentId) { $target = $i; break; }
        if ($target === null) { flock($handle, LOCK_UN); fclose($handle); quebec_json(404, ['error' => 'Kommentar nicht gefunden']); }
        if (($comments[$target]['profile'] ?? '') !== $currentProfile) { flock($handle, LOCK_UN); fclose($handle); quebec_json(403, ['error' => 'Du kannst nur deinen eigenen Kommentar löschen']); }
        $isRoot = empty($comments[$target]['parentId']);
        $hasReplies = $isRoot && count(array_filter($comments, fn($c) => ($c['parentId'] ?? '') === $commentId)) > 0;
        if ($hasReplies) { $comments[$target]['deleted'] = true; $comments[$target]['profile'] = null; $comments[$target]['text'] = ''; }
        else array_splice($comments, $target, 1);
        $data['comments'][$decision] = array_values($comments);
    } else {
        flock($handle, LOCK_UN); fclose($handle); quebec_json(422, ['error' => 'Aktion nicht unterstützt']);
    }
    rewind($handle); ftruncate($handle, 0);
    fwrite($handle, json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES));
    fflush($handle); flock($handle, LOCK_UN); fclose($handle);
    quebec_json(200, quebec_view($data, $currentProfile));
}

canada_require_login();
$profileId = canada_profile();
$profile = CANADA_PROFILES[$profileId];
?>
