<script>
const qDecisionConfig={history:{number:"1",title:"Québec historisch kennenlernen",question:"Wie wichtig ist dir, Québec nicht nur anzusehen, sondern seine Geschichte durch eine Führung oder gezielte historische Besichtigung kennenzulernen?",options:[{id:"individuell",label:"Individuell",text:"3–4 Std. · maximale Freiheit · weitgehend kostenlos",meta:"Atmosphäre: frei und spontan · Anspruch: mittel · Plus: eigenes Tempo · Minus: weniger historischer Kontext"},{id:"klassisch",label:"Klassische Führung",text:"ca. 2 Std. · kompakt, sachlich und effizient",meta:"Atmosphäre: informativ · Anspruch: leicht–mittel · Preis: grob 30–40 CAD · Plus: viel Kontext in kurzer Zeit"},{id:"figur",label:"Historische Figurenführung",text:"ca. 2 Std. · Geschichte als Storytelling",meta:"Atmosphäre: lebendig und unterhaltsam · Anspruch: leicht–mittel · Plus: memorabler · Minus: weniger nüchtern"}]},nature:{number:"2",title:"Naturausflug außerhalb der Stadt",question:"Wie wichtig ist dir, einen Teil unseres einzigen vollen Tages für Natur oder Landschaft außerhalb Québecs zu verwenden?",options:[{id:"montmorency",label:"Nur Montmorency individuell",text:"2½–3 Std. gesamt · mit unserem Mietwagen",meta:"Erlebnis: Wasserfall und Aussicht · Anspruch: leicht–mittel · Preis: niedrig–mittel · Plus: Stadtzeit bleibt"},{id:"combo",label:"Montmorency + Île d’Orléans",text:"ca. 4½ Std. · deutlich größerer Ausflug",meta:"Erlebnis: Natur + ländliches Québec · Anspruch: leicht · Preis: mittel · Minus: viel weniger Stadt"},{id:"island",label:"Île d’Orléans stärker gewichten",text:"4–5 Std. · Genuss und Landschaft",meta:"Erlebnis: Cidre, Landwirtschaft, Dörfer · Anspruch: leicht · Minus: klare Entscheidung gegen viel Québec City"}]},citadelle:{number:"3",title:"Citadelle & Militärgeschichte",question:"Wie wichtig ist dir die militärhistorische Seite Québecs?",options:[{id:"citadelle",label:"Citadelle",text:"1½–2 Std. · Führung + Museum",meta:"Atmosphäre: historisch · Anspruch: mittel · Preis: etwa 20–22 CAD (2026)"},{id:"plains",label:"Nur Plains of Abraham",text:"45–90 Min. · frei und flexibel",meta:"Atmosphäre: Park + Geschichte · Anspruch: leicht · Preis: kostenlos"},{id:"both",label:"Kombination",text:"2½–3 Std. · historisch am vollständigsten",meta:"Plus: viel Kontext · Minus: großer Teil des Nachmittags"}]},foodtour:{number:"4",title:"Kulinarische Führung",question:"Wie sehr möchtest du Québec über eine geführte Food Tour kennenlernen?",options:[{id:"food",label:"Food Tour mit vielen Kostproben",text:"ca. 3 Std. · Essen im Mittelpunkt",meta:"Atmosphäre: gesellig · Anspruch: leicht · Preis: eher hoch · ersetzt einen großen Teil des Mittagessens"},{id:"histfood",label:"Historische Food Tour",text:"ca. 3 Std. · Essen + mehr Geschichte",meta:"Atmosphäre: erzählerisch · Preis: eher hoch · Plus: zwei Themen in einem Block"},{id:"dinner",label:"Keine Food Tour",text:"Zeit und Budget lieber in ein besonderes Dinner",meta:"Plus: mehr freie Stadtzeit · Dienstagabend wird gastronomischer Schwerpunkt"}]},night:{number:"5",title:"Québec bei Nacht",question:"Wie wichtig ist dir nach dem Abendessen noch ein bewusstes Nacht-Erlebnis?",options:[{id:"walk",label:"Nachtspaziergang",text:"60–90 Min. · kostenlos und flexibel",meta:"Atmosphäre: ruhig, romantisch · Anspruch: leicht–mittel · jederzeit abbrechbar"},{id:"ferry",label:"Lévis-Fähre",text:"45–70 Min. · Skyline vom Sankt-Lorenz-Strom",meta:"Atmosphäre: Aussicht · Anspruch: sehr leicht · sehr gutes Zeit/Erlebnis-Verhältnis"},{id:"ghost",label:"Ghost Tour",text:"ca. 90 Min. · geführt und unterhaltsam",meta:"Atmosphäre: Geschichten und Legenden · Dinner muss früher und kompakter sein"}]},restaurant:{number:"R",title:"Restaurantstil für den besonderen Abend",question:"Wie wichtig ist dir, dass mindestens einer der beiden Abende ein bewusst geplantes besonderes Restaurant-Erlebnis wird?",options:[{id:"traditional",label:"Traditionelle Québec-Küche",text:"Tourtière, Wild, Erbsensuppe, Ahorn",meta:"Atmosphäre: historisch/herzhaft · Preis: mittel–gehoben"},{id:"regional",label:"Moderne regionale Québec-Küche",text:"lokale Produkte zeitgemäß interpretiert",meta:"Atmosphäre: kreativ · Preis: mittel–gehoben"},{id:"bistro",label:"Bistro / Brasserie",text:"französisch geprägt, ungezwungen, vollständige Karte",meta:"Atmosphäre: klassisch und entspannt · Preis: mittel–gehoben"},{id:"steak",label:"Steak & Seafood",text:"Fleisch, Fisch und Meeresfrüchte im Mittelpunkt",meta:"Atmosphäre: klassisches Steakhouse · Preis: gehoben"},{id:"fine",label:"Fine Dining",text:"mehrgängiges Menü – das Essen ist das Abendprogramm",meta:"Atmosphäre: gastronomisch inszeniert · Preis: hoch"},{id:"casual",label:"Unkomplizierte lokale Küche",text:"regional, gemütlich, weniger formell",meta:"Atmosphäre: locker · Preis: mittel · besonders passend am Montag"}]}};
let qState=null,qCsrf="";const qEsc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));function qDate(v){try{return new Intl.DateTimeFormat("de-DE",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(v))}catch{return ""}}async function qAuth(){const r=await fetch("auth.php",{cache:"no-store"});if(r.status===401){location.href="login.php?next="+encodeURIComponent(location.pathname);throw new Error("login")}const p=await r.json();qCsrf=p.csrf}async function qLoad(){await qAuth();const r=await fetch("04-quebec-city.php?api=1&t="+Date.now(),{cache:"no-store"});if(!r.ok)throw new Error("Abstimmung konnte nicht geladen werden");qState=await r.json();qRenderAll()}async function qSave(body){const r=await fetch("04-quebec-city.php?api=1",{method:"POST",headers:{"Content-Type":"application/json","X-CSRF-Token":qCsrf},body:JSON.stringify(body)});const p=await r.json().catch(()=>({}));if(r.status===401){location.href="login.php?next="+encodeURIComponent(location.pathname);return}if(!r.ok)throw new Error(p.error||"Speichern nicht möglich");qState=p;qRenderAll()}function qStars(id,pid,value){const current=pid===qState.currentProfile;return `<div class="q-stars">${[1,2,3,4,5].map(n=>current?`<button type="button" class="${n<=value?'filled':''}" data-q-rating="${id}" data-value="${n}" aria-label="${n} Sterne">★</button>`:`<span class="${n<=value?'filled':''}">★</span>`).join('')}</div>`}function qComments(id){const all=Array.isArray(qState.comments?.[id])?qState.comments[id]:[],roots=all.filter(c=>!c.parentId),profile=qState.profiles;const rows=roots.map(c=>{const deleted=!!c.deleted,a=deleted?{name:"Gelöscht",avatar:""}:(profile[c.profile]||{name:c.profile,avatar:""});const replies=all.filter(r=>r.parentId===c.id).map(r=>{const ra=profile[r.profile]||{name:r.profile,avatar:""};return `<div class="q-comment q-reply"><i class="avatar ${qEsc(ra.avatar)}"></i><div><header><strong>${qEsc(ra.name)}</strong><span>${qDate(r.createdAt)} ${r.profile===qState.currentProfile?`<button class="q-delete" data-q-delete="${id}" data-comment="${r.id}">Löschen</button>`:''}</span></header><p>${qEsc(r.text)}</p></div></div>`}).join('');return `<div class="q-comment"><i class="avatar ${qEsc(a.avatar)}"></i><div><header><strong>${qEsc(a.name)}</strong><span>${qDate(c.createdAt)} ${!deleted&&c.profile===qState.currentProfile?`<button class="q-delete" data-q-delete="${id}" data-comment="${c.id}">Löschen</button>`:''}</span></header>${deleted?'<p><i>Kommentar gelöscht</i></p>':`<p>${qEsc(c.text)}</p><details><summary>Antworten</summary><form class="q-reply-form" data-q-comment-form="${id}" data-parent="${c.id}"><textarea maxlength="1000" required placeholder="Antwort schreiben …"></textarea><button>Antwort senden</button></form></details>`}${replies}</div></div>`}).join('');return `<details class="q-discussion"><summary>Kommentare (${all.filter(c=>!c.deleted).length})</summary><form class="q-comment-form" data-q-comment-form="${id}"><textarea maxlength="1000" required placeholder="Was denkst du über diese Entscheidung?"></textarea><button>Als ${qEsc(qState.profiles[qState.currentProfile]?.name||'Profil')} kommentieren</button></form>${rows||'<p class="q-save-note">Noch kein Kommentar.</p>'}</details>`}function qDecisionHtml(id){const cfg=qDecisionConfig[id],ratings=qState.ratings?.[id]||{},choices=qState.choices?.[id]||{},avg=qState.averages?.[id];const people=Object.entries(qState.profiles).map(([pid,p])=>`<div class="q-person ${pid===qState.currentProfile?'current':''}"><strong>${qEsc(p.name)}${pid===qState.currentProfile?' · du':''}</strong>${qStars(id,pid,Number(ratings[pid]||0))}<small>${ratings[pid]?ratings[pid]+'/5':'offen'}</small></div>`).join('');const options=cfg.options.map(o=>{const voters=Object.entries(choices).filter(([,c])=>c===o.id).map(([pid])=>qState.profiles[pid]?.name).filter(Boolean);return `<button type="button" class="q-option ${choices[qState.currentProfile]===o.id?'selected':''}" data-q-choice="${id}" data-choice="${o.id}"><strong>${qEsc(o.label)}</strong><small>${qEsc(o.text)}</small><span class="q-option-meta">${qEsc(o.meta)}</span><span class="q-option-voters">${voters.length?qEsc(voters.join(', ')):'Noch keine Stimme'}</span></button>`}).join('');const roster=Object.entries(qState.profiles).map(([pid,p])=>{const picked=cfg.options.find(o=>o.id===choices[pid]);return `<div class="q-person ${pid===qState.currentProfile?'current':''}"><strong>${qEsc(p.name)}${pid===qState.currentProfile?' · du':''}</strong><small>${picked?qEsc(picked.label):'noch offen'}</small></div>`}).join('');return `<article class="q-decision-shell"><div class="q-decision-head"><div class="q-decision-num">${cfg.number}</div><div><h3>${qEsc(cfg.title)}</h3><p>${qEsc(cfg.question)}</p></div></div><div class="q-step"><div class="q-step-head"><b>1 · Grundsatzentscheidung</b><small>5 = unbedingt · 1 = kann entfallen · Ø ${avg?.average??'–'}</small></div><div class="q-rating-grid">${people}</div></div><div class="q-step"><div class="q-step-head"><b>2 · Variantenentscheidung</b><small>unabhängig von Schritt 1 · später änderbar</small></div><div class="q-options">${options}</div><div class="q-choice-roster">${roster}</div></div>${qComments(id)}</article>`}function qRenderAll(){const ids=['history','nature','citadelle','foodtour','night'];document.querySelector('#q-decisions').innerHTML=ids.map(qDecisionHtml).join('');document.querySelector('#q-restaurant-decision').innerHTML=qDecisionHtml('restaurant');const all=[...ids,'restaurant'];document.querySelector('#q-summary-grid').innerHTML=all.map(id=>{const cfg=qDecisionConfig[id],avg=qState.averages?.[id]?.average,choices=qState.choices?.[id]||{},counts={};Object.values(choices).forEach(c=>counts[c]=(counts[c]||0)+1);const fav=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0]?.[0],label=cfg.options.find(o=>o.id===fav)?.label||'noch keine Variante';return `<div class="q-summary-item"><small>${qEsc(cfg.title)}</small><b>${avg??'–'} / 5</b><br>${qEsc(label)}</div>`}).join('')}document.addEventListener('click',async e=>{const r=e.target.closest('[data-q-rating]');if(r){try{await qSave({action:'rating',decision:r.dataset.qRating,rating:Number(r.dataset.value)})}catch(err){alert(err.message)}return}const c=e.target.closest('[data-q-choice]');if(c){try{await qSave({action:'choice',decision:c.dataset.qChoice,choice:c.dataset.choice})}catch(err){alert(err.message)}return}const d=e.target.closest('[data-q-delete]');if(d){if(!confirm('Eigenen Kommentar löschen?'))return;try{await qSave({action:'delete-comment',decision:d.dataset.qDelete,commentId:d.dataset.comment})}catch(err){alert(err.message)}}});document.addEventListener('submit',async e=>{const f=e.target.closest('[data-q-comment-form]');if(!f)return;e.preventDefault();const text=f.querySelector('textarea').value.trim();if(!text)return;try{await qSave({action:'comment',decision:f.dataset.qCommentForm,text,parentId:f.dataset.parent||''})}catch(err){alert(err.message)}});qLoad().catch(err=>{document.querySelector('#q-decisions').innerHTML=`<div class="q-error">${qEsc(err.message)}</div>`});
</script><script src="app.js?v=20260906-4"></script></body></html>
